test('addLine rejects invalid discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: 150 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
});

test('createInvoice applies gold tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice with explicit discountPercent overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice with explicit 0 discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice with multiple lines applies tier discount to all', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('createInvoice with mixed explicit and tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 15 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 15);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('createInvoice with tier discount affects total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 850000);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.total, 807500);
});

test('createInvoice gold vs standard tier difference', () => {
