test('renderInvoiceText with multiple discounted lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
